#!/usr/bin/env node
/**
 * Builds `docs/board.html`, the task board, from the two files that already own the facts:
 * `docs/CHANGELOG.md` (what is done) and `docs/BACKLOG.md` (what is ahead, closed or rejected),
 * plus the change folders under `docs/plans/` (what is in progress). The board restates nothing by
 * hand: a hand-kept board would be a third copy of the ledger, and two copies of one fact drift
 * (`FX-023`, `FX-027`). It is regenerated by the pre-commit hook and checked by `PR-API-10` (`CH-040`).
 *
 *   node scripts/board.mjs          # write docs/board.html
 *   node scripts/board.mjs check    # exit 1 if docs/board.html is stale
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const repoRoot = path.resolve(import.meta.dirname, '..');
const OUT = path.join(repoRoot, 'docs', 'board.html');

const read = (rel) => fs.readFileSync(path.join(repoRoot, rel), 'utf8');

/** Splits a markdown table row on unescaped pipes; `\|` inside a cell stays a pipe. */
function cells(line) {
  return line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split(/(?<!\\)\|/)
    .map((cell) => cell.trim().replace(/\\\|/g, '|'));
}

/** Every table under a `## heading`, as objects keyed by the header row. */
function tables(markdown) {
  const out = [];
  let heading = '';
  const lines = markdown.split(/\r?\n/);
  for (let i = 0; i < lines.length; i += 1) {
    const h = /^#{2,3}\s+(.*)$/.exec(lines[i]);
    if (h) heading = h[1].trim();
    if (lines[i].startsWith('|') && /^\|\s*-/.test(lines[i + 1] ?? '')) {
      const header = cells(lines[i]);
      const rows = [];
      let j = i + 2;
      for (; j < lines.length && lines[j].startsWith('|'); j += 1) {
        const values = cells(lines[j]);
        rows.push(Object.fromEntries(header.map((key, k) => [key, values[k] ?? ''])));
      }
      out.push({ heading, rows });
      i = j - 1;
    }
  }
  return out;
}

const escape = (text) =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** The ledger's inline markdown: `code` and **bold**, nothing else. */
const inline = (text) =>
  escape(text)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

/** A title: the first sentence, without markdown, cut at a word near 150 characters. */
/** A backlog row whose `What` opens with this marker is a known, unfixed defect (`CH-043`). */
const DEFECT_MARKER = /^\*\*Defect\.\*\*\s*/;

function title(text) {
  const plain = text
    .replace(/\*\*Closed by[^*]*\*\*\s*/, '')
    .replace(DEFECT_MARKER, '')
    .replace(/[`*]/g, '');
  const first = plain.split(/(?<=[.!?])\s+(?=[A-Z(`])/)[0];
  if (first.length <= 150) return first;
  return first.slice(0, 150).replace(/\s+\S*$/, '') + 'â€¦';
}

function remoteUrl() {
  try {
    const url = execFileSync('git', ['remote', 'get-url', 'origin'], { cwd: repoRoot })
      .toString()
      .trim();
    return url.replace(/^git@github\.com:/, 'https://github.com/').replace(/\.git$/, '');
  } catch {
    return null;
  }
}

/**
 * A change is done once the ledger cites a commit that touched its folder: the ledger row names
 * the commit, not always the folder. A folder no cited commit touched is still in progress.
 */
function folderCommitCited(slug, changelog) {
  try {
    const hashes = execFileSync(
      'git',
      ['log', '--format=%h', '--abbrev=7', '--', `docs/plans/${slug}`],
      { cwd: repoRoot },
    )
      .toString()
      .split(/\s+/)
      .filter(Boolean);
    return hashes.some((hash) => changelog.includes(`\`${hash}`));
  } catch {
    return false;
  }
}

function collect() {
  const changelog = read('docs/CHANGELOG.md');
  const backlog = read('docs/BACKLOG.md');
  const done = [];

  for (const { heading, rows } of tables(changelog)) {
    const kind = /^Features/.test(heading)
      ? 'feature'
      : /^Process/.test(heading)
        ? 'process'
        : /^Defects/.test(heading)
          ? 'fix'
          : null;
    if (kind === null) continue;
    for (const row of rows) {
      if (!/^(FT|CH|FX)-\d+$/.test(row.ID)) continue;
      const text = row.What ?? row.Defect ?? '';
      const pathMarker = /Path: (full|short)[^|]*/.exec(text)?.[0] ?? '';
      done.push({
        id: row.ID,
        kind,
        date: row.Date,
        title: title(text),
        text,
        foundBy: row['Found by'] ?? '',
        commit: (row.Commit ?? '').replace(/`/g, ''),
        path: pathMarker,
      });
    }
  }

  const open = [];
  const closed = [];
  let rejected = [];
  for (const { heading, rows } of tables(backlog)) {
    if (/^Open/.test(heading)) {
      for (const row of rows) {
        if (!/^BL-\d+$/.test(row.ID)) continue;
        const closedBy = /^\*\*Closed by ([^*]+?)\.?\*\*/.exec(row.What);
        const item = {
          id: row.ID,
          priority: row.P,
          area: row.Area,
          type: DEFECT_MARKER.test(row.What) ? 'defect' : 'task',
          title: title(row.What),
          text: row.What,
          dependsOn: row['Depends on'],
          conflicts: row['Conflicts with'],
        };
        if (closedBy) closed.push({ ...item, closedBy: closedBy[1].replace(/`/g, '') });
        else open.push(item);
      }
    } else if (/^Closed/.test(heading)) {
      for (const row of rows) {
        if (!/^BL-\d+$/.test(row.ID)) continue;
        closed.push({
          id: row.ID,
          area: '',
          title: title(row['What it was']),
          text: row['What it was'],
          closedBy: row['Closed by'].replace(/`/g, ''),
        });
      }
    } else if (/^Rejected/.test(heading)) {
      rejected = rows.map((row) => ({ title: row.What, why: row['Why rejected'] }));
    }
  }

  const plansDir = path.join(repoRoot, 'docs', 'plans');
  const inProgress = fs
    .readdirSync(plansDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((slug) => !changelog.includes(slug) && !folderCommitCited(slug, changelog))
    .map((slug) => {
      const plan = path.join(plansDir, slug, `${slug}.plan.md`);
      const first = fs.existsSync(plan)
        ? (/^#\s+(.*)$/m.exec(fs.readFileSync(plan, 'utf8'))?.[1] ?? slug)
        : slug;
      return { slug, title: first };
    });

  const byNumber = (a, b) => Number(b.id.slice(3)) - Number(a.id.slice(3));
  done.sort((a, b) => (b.date === a.date ? byNumber(a, b) : b.date.localeCompare(a.date)));
  open.sort((a, b) => a.priority.localeCompare(b.priority) || byNumber(a, b));
  closed.sort(byNumber);

  return { done, open, closed, rejected, inProgress, epics: readEpics(), remote: remoteUrl() };
}

/**
 * `docs/EPICS.md`: one `## EP-NN Â· Name` section per epic with `Kind`, `What it gives` and
 * `Members` lines. Every ledger and backlog ID sits in exactly one epic (`LG-API-08`).
 */
export function readEpics(markdown = read('docs/EPICS.md')) {
  const field = (text, name) =>
    new RegExp(`^- \\*\\*${name}:\\*\\*\\s*(.+)$`, 'm').exec(text)?.[1]?.trim() ?? '';
  const ids = (text) => [...text.matchAll(/(FT|CH|FX|BL)-\d+/g)].map((m) => m[0]);
  const epics = [];
  for (const section of markdown.split(/^## /m).slice(1)) {
    const head = /^(EP-\d+)\s*Â·\s*(.+)$/m.exec(section);
    if (head === null) continue;
    const [epicPart, ...featureParts] = section.split(/^### /m);
    const features = featureParts.flatMap((part) => {
      const fh = /^(F-\d+)\s*Â·\s*(.+)$/m.exec(part);
      if (fh === null) return [];
      return [
        {
          id: fh[1],
          name: fh[2].trim(),
          gives: field(part, 'What it gives'),
          tasks: ids(field(part, 'Tasks')),
        },
      ];
    });
    epics.push({
      id: head[1],
      name: head[2].trim(),
      kind: field(epicPart, 'Kind'),
      gives: field(epicPart, 'What it gives'),
      features,
      members: features.flatMap((feature) => feature.tasks),
    });
  }
  return epics;
}

function render({ done, open, closed, rejected, inProgress, epics, remote }) {
  const latest = done[0]?.date ?? '';
  const kindLabel = { feature: 'Feature', process: 'Process', fix: 'Fix' };
  const commitLink = (hash) =>
    /^[0-9a-f]{7,40}$/.test(hash) && remote
      ? `<a href="${remote}/commit/${hash}" target="_blank" rel="noopener"><code>${hash}</code></a>`
      : `<code>${escape(hash)}</code>`;

  const backlogCard = (item) => `
      <details class="card ${item.type}" data-search="${escape(`${item.id} ${item.type} ${item.area} ${item.text}`.toLowerCase())}">
        <summary>
          <span class="id">${item.id}</span>
          ${item.type === 'defect' ? '<span class="chip type-defect">Defect</span>' : ''}
          <span class="chip area">${escape(item.area)}</span>
          <span class="title">${inline(item.title)}</span>
        </summary>
        <div class="body">
          <p>${inline(item.text)}</p>
          ${item.dependsOn ? `<p class="meta"><b>Depends on:</b> ${inline(item.dependsOn)}</p>` : ''}
          ${item.conflicts ? `<p class="meta"><b>Conflicts with:</b> ${inline(item.conflicts)}</p>` : ''}
        </div>
      </details>`;

  const column = (priority, label) => {
    const items = open.filter((item) => item.priority === priority);
    return `
    <section class="column p-${priority.toLowerCase()}">
      <h3>${label} <span class="count">${items.length}</span></h3>
      ${items.map(backlogCard).join('') || '<p class="empty">Nothing here.</p>'}
    </section>`;
  };

  const doneById = new Map(done.map((item) => [item.id, item]));
  const openById = new Map(open.map((item) => [item.id, item]));
  const closedById = new Map(closed.map((item) => [item.id, item]));

  const epicCard = (epic) => {
    const openItems = epic.members.filter((id) => openById.has(id)).map((id) => openById.get(id));
    openItems.sort(
      (a, b) =>
        a.priority.localeCompare(b.priority) || Number(b.id.slice(3)) - Number(a.id.slice(3)),
    );
    const shipped = epic.members.filter((id) => doneById.has(id)).map((id) => doneById.get(id));
    shipped.sort((a, b) => b.date.localeCompare(a.date));
    const closedHere = epic.members.filter((id) => closedById.has(id)).length;
    const doneCount = shipped.length + closedHere;
    const total = doneCount + openItems.length;
    const percent = total === 0 ? 100 : Math.round((doneCount / total) * 100);
    const p1 = openItems.filter((item) => item.priority === 'P1').length;
    const status = openItems.length === 0 ? 'Done' : p1 > 0 ? 'Has blocker' : 'Planned';
    const last = shipped[0]?.date ?? 'â€”';
    const next = openItems.slice(0, 3);
    return `
    <details class="epic status-${status.toLowerCase().replace(/ /g, '-')}" data-search="${escape(`${epic.id} ${epic.name} ${epic.gives}`.toLowerCase())}">
      <summary>
        <div class="epic-head">
          <span class="id">${epic.id}</span>
          <span class="epic-name">${escape(epic.name)}</span>
          <span class="badge">${status}</span>
        </div>
        <p class="gives">${inline(epic.gives)}</p>
        <div class="bar" aria-label="${percent}% done"><span style="width:${percent}%"></span></div>
        <p class="meta">${shipped.length} shipped Â· ${openItems.length} open${p1 ? ` Â· <b style="color:var(--p1)">${p1} blocking</b>` : ''} Â· last change ${escape(last)}</p>
        ${next.length ? `<ul class="next">${next.map((item) => `<li><span class="pill p-${item.priority.toLowerCase()}">${item.priority}</span> ${inline(item.title)}</li>`).join('')}</ul>` : '<p class="meta">Nothing open â€” the epic is complete for now.</p>'}
      </summary>
      <div class="body">
        ${openItems.length ? `<h4>Open (${openItems.length})</h4>${openItems.map(backlogCard).join('')}` : ''}
        ${shipped.length ? `<h4>Shipped (${shipped.length})</h4>${shipped.map(doneRow).join('')}` : ''}
      </div>
    </details>`;
  };

  const featureState = (feature) => {
    const openItems = feature.tasks.filter((id) => openById.has(id)).map((id) => openById.get(id));
    openItems.sort((x, y) => x.priority.localeCompare(y.priority));
    const shipped = feature.tasks.filter((id) => doneById.has(id)).map((id) => doneById.get(id));
    shipped.sort((x, y) => y.date.localeCompare(x.date));
    const doneCount = shipped.length + feature.tasks.filter((id) => closedById.has(id)).length;
    const total = doneCount + openItems.length;
    // A ledger row still on `pending` is work not yet committed: its feature is in progress.
    const pending = shipped.some((item) => item.commit === 'pending');
    const status =
      openItems.length === 0 && !pending ? 'done' : doneCount === 0 ? 'planned' : 'progress';
    return { openItems, shipped, doneCount, total, status, last: shipped[0]?.date ?? '' };
  };

  const allFeatures = epics.flatMap((epic) =>
    epic.features.map((feature) => ({ feature, epic, st: featureState(feature) })),
  );

  // The scrum board (`CH-043`): every ticket is a Feature (an `F-NNN` of `docs/EPICS.md`) or a Bug
  // (an open `**Defect.**` backlog row, or a shipped `FX-` row), in To Do, In Progress or Done.
  const parentOf = new Map(
    allFeatures.flatMap(({ feature, epic }) => feature.tasks.map((id) => [id, { feature, epic }])),
  );
  const pillFor = (priority) =>
    priority ? `<span class="pill p-${priority.toLowerCase()}">${priority}</span>` : '';
  const STATUS = { planned: 'todo', progress: 'progress', done: 'done' };

  const tickets = [
    ...allFeatures.map(({ feature, epic, st }) => ({
      type: 'feature',
      id: feature.id,
      title: feature.name,
      epic,
      status: STATUS[st.status],
      priority: st.openItems[0]?.priority ?? '',
      date: st.last,
      feature,
      st,
    })),
    ...open
      .filter((item) => item.type === 'defect')
      .map((item) => ({
        type: 'bug',
        id: item.id,
        title: item.title,
        epic: parentOf.get(item.id)?.epic,
        parent: parentOf.get(item.id)?.feature,
        status: 'todo',
        priority: item.priority,
        date: '',
        item,
      })),
    ...done
      .filter((item) => item.kind === 'fix')
      .map((item) => ({
        type: 'bug',
        id: item.id,
        title: item.title,
        epic: parentOf.get(item.id)?.epic,
        parent: parentOf.get(item.id)?.feature,
        status: item.commit === 'pending' ? 'progress' : 'done',
        priority: '',
        date: item.date,
        shipped: item,
      })),
    ...inProgress.map((change) => ({
      type: /^bugfix\b/i.test(change.title) ? 'bug' : 'feature',
      id: change.slug,
      title: change.title.replace(/^(bugfix|plan):\s*/i, ''),
      epic: undefined,
      status: 'progress',
      priority: '',
      date: '',
      change,
    })),
  ];

  const ticketCard = (t) => {
    const epicName = t.epic ? escape(t.epic.name) : '';
    let meta = '';
    let bar = '';
    let body = '';
    if (t.st) {
      const percent = t.st.total === 0 ? 100 : Math.round((t.st.doneCount / t.st.total) * 100);
      const bugs = t.st.openItems.filter((item) => item.type === 'defect').length;
      meta = `${t.st.doneCount}/${t.st.total} tasks${bugs ? ` Â· <b class="bug-note">${bugs} open bug${bugs > 1 ? 's' : ''}</b>` : ''}`;
      bar = `<div class="bar"><span style="width:${percent}%"></span></div>`;
      body = `<p>${inline(t.feature.gives)}</p>${
        t.st.openItems.length
          ? `<h4>Open tasks (${t.st.openItems.length})</h4>${t.st.openItems.map(backlogCard).join('')}`
          : ''
      }${t.st.shipped.length ? `<h4>Done tasks (${t.st.shipped.length})</h4>${t.st.shipped.map(doneRow).join('')}` : ''}`;
    } else if (t.item) {
      meta = escape(t.item.area);
      body = `<p>${inline(t.item.text)}</p>${t.item.dependsOn && t.item.dependsOn !== 'â€”' ? `<p class="meta"><b>Depends on:</b> ${inline(t.item.dependsOn)}</p>` : ''}`;
    } else if (t.shipped) {
      meta = escape(t.date);
      body = `<p>${inline(t.shipped.text)}</p>${t.shipped.foundBy ? `<p class="meta"><b>Found by:</b> ${inline(t.shipped.foundBy)}</p>` : ''}<p class="meta"><b>Commit:</b> ${commitLink(t.shipped.commit)}</p>`;
    } else if (t.change) {
      meta = 'change folder, no ledger entry yet';
      body = `<p class="meta">Being worked on in <code>docs/plans/${escape(t.change.slug)}/</code>.</p>`;
    }
    const parent = t.parent ? ` Â· ${escape(t.parent.name)}` : '';
    const search = `${t.id} ${t.type} ${t.title} ${epicName} ${t.feature?.tasks.join(' ') ?? ''} ${t.item?.text ?? t.shipped?.text ?? ''}`;
    return `
      <details class="ticket t-${t.type}" data-type="${t.type}" data-epic="${t.epic?.id ?? ''}" data-search="${escape(search.toLowerCase())}">
        <summary>
          <div class="t-top"><span class="type">${t.type === 'bug' ? 'Bug' : 'Feature'}</span>${pillFor(t.priority)}<span class="t-id">${escape(t.id)}</span></div>
          <div class="t-title">${inline(t.title)}</div>
          ${bar}
          <div class="t-meta">${epicName ? `<span class="t-epic">${epicName}</span>${parent} Â· ` : ''}${meta}</div>
        </summary>
        <div class="body">${body}</div>
      </details>`;
  };

  const byPriorityThenDate = (x, y) =>
    (x.priority || 'P9').localeCompare(y.priority || 'P9') || y.date.localeCompare(x.date);
  const PRIORITY_LANES = [
    ['P1', 'P1 Â· Blocking'],
    ['P2', 'P2 Â· Planned'],
    ['P3', 'P3 Â· Nice to have'],
  ];
  const DONE_SHOWN = 12;

  const scrumColumn = (status, label) => {
    const items = tickets.filter((t) => t.status === status);
    let content;
    if (status === 'todo') {
      content = PRIORITY_LANES.map(([priority, laneLabel]) => {
        const lane = items.filter((t) => t.priority === priority).sort(byPriorityThenDate);
        return `<div class="lane p-${priority.toLowerCase()}" data-lane><h4>${laneLabel} <span class="count" data-count>${lane.length}</span></h4>${lane.map(ticketCard).join('') || '<p class="empty">Nothing here.</p>'}</div>`;
      }).join('');
    } else if (status === 'done') {
      const sorted = items.sort((x, y) => y.date.localeCompare(x.date));
      content = `${sorted.map((t, i) => ticketCard(t).replace('<details class="ticket', `<details class="ticket${i >= DONE_SHOWN ? ' more' : ''}`)).join('')}${
        sorted.length > DONE_SHOWN
          ? `<button class="show-all" type="button">Show all ${sorted.length}</button>`
          : ''
      }`;
    } else {
      content =
        items.sort(byPriorityThenDate).map(ticketCard).join('') ||
        '<p class="empty">Nothing is being worked on.</p>';
    }
    return `
      <section class="column scrum-${status}" data-lane>
        <h3>${label} <span class="count" data-count>${items.length}</span></h3>
        ${content}
      </section>`;
  };

  const epicOptions = epics
    .map((epic) => `<option value="${epic.id}">${escape(epic.name)}</option>`)
    .join('');

  const epicGrid = (kind) =>
    epics
      .filter((epic) => epic.kind === kind)
      .map(epicCard)
      .join('');

  const doneRow = (item) => `
      <details class="row ${item.kind}" data-kind="${item.kind}" data-search="${escape(`${item.id} ${item.text}`.toLowerCase())}">
        <summary>
          <span class="date">${escape(item.date)}</span>
          <span class="chip kind">${kindLabel[item.kind]}</span>
          <span class="id">${item.id}</span>
          <span class="title">${inline(item.title)}</span>
        </summary>
        <div class="body">
          <p>${inline(item.text)}</p>
          ${item.foundBy ? `<p class="meta"><b>Found by:</b> ${inline(item.foundBy)}</p>` : ''}
          <p class="meta"><b>Commit:</b> ${commitLink(item.commit)}</p>
        </div>
      </details>`;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PurpleSchool board</title>
<!-- Generated by scripts/board.mjs from docs/CHANGELOG.md, docs/BACKLOG.md and docs/plans/. Do not edit by hand. -->
<style>
:root {
  --bg: #f4f4f7; --surface: #ffffff; --text: #1d1b26; --muted: #5f5b70; --line: #e3e1ea;
  --accent: #6c4ee0; --p1: #c62828; --p2: #b26a00; --p3: #2e7d5b;
  --feature: #6c4ee0; --process: #2563a8; --fix: #c62828; --code: #f0eefa;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14131a; --surface: #1e1c27; --text: #ecebf2; --muted: #a29fb3; --line: #2e2b3b;
    --accent: #a594ff; --p1: #ff7a7a; --p2: #f2b04f; --p3: #5fd3a0;
    --feature: #a594ff; --process: #7fb3ff; --fix: #ff7a7a; --code: #2a2738;
  }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text);
  font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
header { padding: 28px 16px 8px; max-width: 1280px; margin: 0 auto; }
h1 { margin: 0 0 4px; font-size: 26px; letter-spacing: -0.01em; }
.sub { color: var(--muted); margin: 0; }
main { max-width: 1280px; margin: 0 auto; padding: 0 16px 48px; }
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin: 20px 0; }
.stat { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; }
.stat .n { font-size: 28px; font-weight: 700; line-height: 1.1; }
.stat .l { color: var(--muted); font-size: 13px; }
.toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0 16px; }
.tabs button, .filters button { border: 1px solid var(--line); background: var(--surface); color: var(--text);
  padding: 7px 14px; border-radius: 999px; cursor: pointer; font: inherit; }
.tabs button[aria-selected="true"], .filters button[aria-pressed="true"] { background: var(--accent); color: #fff; border-color: var(--accent); }
input[type=search] { flex: 1; min-width: 200px; padding: 8px 12px; border-radius: 999px;
  border: 1px solid var(--line); background: var(--surface); color: var(--text); font: inherit; }
.panel[hidden] { display: none; }
.board { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; align-items: start; }
.column { background: color-mix(in srgb, var(--surface) 60%, transparent); border: 1px solid var(--line); border-radius: 14px; padding: 12px; }
.column h3 { margin: 4px 4px 12px; font-size: 15px; display: flex; align-items: center; gap: 8px; }
.column h3::before { content: ""; width: 10px; height: 10px; border-radius: 50%; background: var(--accent); }
.p-p1 h3::before { background: var(--p1); } .p-p2 h3::before { background: var(--p2); } .p-p3 h3::before { background: var(--p3); }
.count { margin-left: auto; color: var(--muted); font-weight: 500; }
.card, .row { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; margin-bottom: 8px; }
.card summary, .row summary { list-style: none; cursor: pointer; padding: 10px 12px; display: flex; flex-wrap: wrap; gap: 6px 8px; align-items: baseline; }
.card summary::-webkit-details-marker, .row summary::-webkit-details-marker { display: none; }
.card[open], .row[open] { border-color: var(--accent); }
.title { flex: 1 1 100%; }
.row .title { flex: 1 1 320px; }
.id { font-weight: 700; font-variant-numeric: tabular-nums; }
.date { color: var(--muted); font-variant-numeric: tabular-nums; min-width: 88px; }
.chip { font-size: 12px; padding: 1px 8px; border-radius: 999px; border: 1px solid var(--line); color: var(--muted); }
.row.feature .kind { color: var(--feature); border-color: var(--feature); }
.row.process .kind { color: var(--process); border-color: var(--process); }
.row.fix .kind { color: var(--fix); border-color: var(--fix); }
.chip.type-defect { color: var(--fix); border-color: var(--fix); font-weight: 600; }
.card.defect { border-left: 4px solid var(--fix); }
.body { padding: 0 12px 12px; border-top: 1px solid var(--line); }
.body p { margin: 10px 0 0; overflow-wrap: anywhere; }
.meta { color: var(--muted); font-size: 14px; }
code { background: var(--code); padding: 0 4px; border-radius: 4px; font-size: 0.9em; }
a { color: var(--accent); }
.empty { color: var(--muted); padding: 4px; }
.progress .card { border-left: 4px solid var(--accent); }
table { width: 100%; border-collapse: collapse; background: var(--surface); border-radius: 10px; overflow: hidden; }
td, th { text-align: left; vertical-align: top; padding: 10px 12px; border-bottom: 1px solid var(--line); }
th { color: var(--muted); font-weight: 600; font-size: 13px; }
.hidden, .off { display: none; }
h2 { font-size: 17px; margin: 24px 4px 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }
.epics { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 16px; align-items: start; }
.epic { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; border-top: 4px solid var(--accent); }
.epic.status-done { border-top-color: var(--p3); }
.epic.status-has-blocker { border-top-color: var(--p1); }
.epic summary { list-style: none; cursor: pointer; padding: 14px 16px; }
.epic summary::-webkit-details-marker { display: none; }
.epic-head { display: flex; align-items: center; gap: 8px; }
.epic-name { font-weight: 700; font-size: 17px; flex: 1; }
.badge { font-size: 12px; padding: 2px 10px; border-radius: 999px; background: var(--code); color: var(--accent); font-weight: 600; }
.status-done .badge { color: var(--p3); } .status-has-blocker .badge { color: var(--p1); }
.gives { margin: 8px 0 10px; }
.bar { height: 8px; background: var(--line); border-radius: 999px; overflow: hidden; }
.bar span { display: block; height: 100%; background: var(--accent); }
.status-done .bar span { background: var(--p3); }
.next { margin: 10px 0 0; padding: 0; list-style: none; }
.next li { margin: 4px 0; font-size: 14px; }
.pill { font-size: 11px; font-weight: 700; padding: 0 6px; border-radius: 6px; color: #fff; }
.pill.p-p1 { background: var(--p1); } .pill.p-p2 { background: var(--p2); } .pill.p-p3 { background: var(--p3); }
.epic .body h4 { margin: 14px 0 8px; font-size: 13px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; }
.epic[open] { grid-column: 1 / -1; }
.feature { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; margin-bottom: 10px; }
.feature summary { list-style: none; cursor: pointer; padding: 12px 14px; }
.feature summary::-webkit-details-marker { display: none; }
.feature[open] { border-color: var(--accent); }
.feature-head { display: flex; gap: 6px; align-items: center; justify-content: space-between; }
.feature-name { font-weight: 700; font-size: 16px; margin-top: 6px; }
.epic-chip { color: var(--accent); border-color: var(--accent); }
.feature .gives { font-size: 14px; margin: 4px 0 8px; }
.kanban-planned h3::before { background: var(--muted); } .kanban-progress h3::before { background: var(--accent); } .kanban-done h3::before { background: var(--p3); }
.kanban-done .bar span { background: var(--p3); }
.epic-filter button { font-size: 13px; padding: 5px 12px; }
.epic-filter button[aria-pressed="true"] { background: var(--accent); color: #fff; border-color: var(--accent); }
.scrum { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; align-items: start; }
@media (max-width: 900px) { .scrum { grid-template-columns: 1fr; } }
.scrum-todo h3::before { background: var(--muted); } .scrum-progress h3::before { background: var(--accent); } .scrum-done h3::before { background: var(--p3); }
.lane { margin-bottom: 14px; }
.lane h4 { margin: 6px 4px 8px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); display: flex; gap: 8px; align-items: center; }
.lane h4::before { content: ""; width: 4px; height: 14px; border-radius: 2px; background: var(--muted); }
.lane.p-p1 h4::before { background: var(--p1); } .lane.p-p2 h4::before { background: var(--p2); } .lane.p-p3 h4::before { background: var(--p3); }
.ticket { background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--feature); border-radius: 10px; margin-bottom: 8px; }
.ticket.t-bug { border-left-color: var(--fix); }
.ticket summary { list-style: none; cursor: pointer; padding: 10px 12px; }
.ticket summary::-webkit-details-marker { display: none; }
.ticket[open] { border-color: var(--accent); border-left-width: 4px; }
.ticket .body h4 { margin: 12px 0 6px; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; }
.t-top { display: flex; align-items: center; gap: 6px; }
.type { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; padding: 1px 7px; border-radius: 6px; color: var(--feature); background: var(--code); }
.t-bug .type { color: var(--fix); }
.t-id { margin-left: auto; color: var(--muted); font-size: 12px; font-variant-numeric: tabular-nums; }
.t-title { font-weight: 600; margin: 6px 0; overflow-wrap: anywhere; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.ticket[open] .t-title { display: block; }
.t-meta { color: var(--muted); font-size: 13px; }
.t-epic { color: var(--accent); }
.ticket .bar { height: 5px; margin: 4px 0 6px; }
.scrum-done .bar span { background: var(--p3); }
.bug-note { color: var(--fix); }
.ticket.more { display: none; }
.scrum-done.expanded .ticket.more { display: block; }
.scrum-done.expanded .ticket.more.hidden { display: none; }
.show-all { width: 100%; padding: 8px; border: 1px dashed var(--line); background: transparent; color: var(--accent); border-radius: 10px; cursor: pointer; font: inherit; }
#epic { padding: 7px 12px; border-radius: 999px; border: 1px solid var(--line); background: var(--surface); color: var(--text); font: inherit; }
.now { background: var(--surface); border: 1px solid var(--accent); border-radius: 14px; padding: 4px 16px 10px; }
@media (max-width: 600px) { .date { min-width: 0; } }
</style>
</head>
<body>
<header>
  <h1>PurpleSchool board</h1>
  <p class="sub">Built from the ledger and the backlog by <code>scripts/board.mjs</code>. Latest ledger entry: ${escape(latest)}.</p>
</header>
<main>
  <div class="stats">
    <div class="stat"><div class="n">${tickets.filter((t) => t.status === 'todo').length}</div><div class="l">To do</div></div>
    <div class="stat"><div class="n">${tickets.filter((t) => t.status === 'progress').length}</div><div class="l">In progress</div></div>
    <div class="stat"><div class="n">${tickets.filter((t) => t.status === 'done').length}</div><div class="l">Done</div></div>
    <div class="stat"><div class="n" style="color:var(--fix)">${tickets.filter((t) => t.type === 'bug' && t.status !== 'done').length}</div><div class="l">Open bugs</div></div>
    <div class="stat"><div class="n" style="color:var(--p1)">${tickets.filter((t) => t.status !== 'done' && t.priority === 'P1').length}</div><div class="l">P1 tickets</div></div>
    <div class="stat"><div class="n">${epics.length}</div><div class="l">Epics</div></div>
  </div>

  <div class="toolbar">
    <div class="tabs" role="tablist">
      <button role="tab" aria-selected="true" data-tab="scrum">Board</button>
      <button role="tab" aria-selected="false" data-tab="epics">Epics</button>
      <button role="tab" aria-selected="false" data-tab="board">Backlog</button>
      <button role="tab" aria-selected="false" data-tab="done">Done</button>
      <button role="tab" aria-selected="false" data-tab="closed">Closed backlog</button>
      <button role="tab" aria-selected="false" data-tab="rejected">Rejected</button>
    </div>
    <input type="search" id="q" placeholder="Search by ID or textâ€¦" aria-label="Search">
  </div>

  <div class="panel" id="scrum">
    <div class="toolbar">
      <div class="filters type-filter">
        <button aria-pressed="true" data-type-filter="all">All</button>
        <button aria-pressed="false" data-type-filter="feature">Features</button>
        <button aria-pressed="false" data-type-filter="bug">Bugs</button>
      </div>
      <select id="epic" aria-label="Epic"><option value="all">All epics</option>${epicOptions}</select>
    </div>
    <div class="scrum">
      ${scrumColumn('todo', 'To Do')}
      ${scrumColumn('progress', 'In Progress')}
      ${scrumColumn('done', 'Done')}
    </div>
  </div>

  <div class="panel" id="epics" hidden>
    ${
      inProgress.length
        ? `<section class="now"><h2>In progress now</h2>${inProgress.map((item) => `<p><b>${escape(item.slug)}</b> â€” ${inline(item.title)}</p>`).join('')}</section>`
        : ''
    }
    <h2>Product</h2>
    <div class="epics">${epicGrid('product')}</div>
    <h2>Technical</h2>
    <div class="epics">${epicGrid('technical')}</div>
  </div>

  <div class="panel" id="board" hidden>
    <div class="board">
      <section class="column progress">
        <h3>In progress <span class="count">${inProgress.length}</span></h3>
        ${
          inProgress
            .map(
              (item) => `
        <div class="card"><div class="body" style="border:0;padding:10px 12px">
          <span class="id">${escape(item.slug)}</span>
          <p>${inline(item.title)}</p>
          <p class="meta">A change folder in <code>docs/plans/${escape(item.slug)}/</code> with no ledger entry yet.</p>
        </div></div>`,
            )
            .join('') ||
          '<p class="empty">No change is open: every change folder has its ledger entry.</p>'
        }
      </section>
      ${column('P1', 'P1 Â· Blocking')}
      ${column('P2', 'P2 Â· Planned')}
      ${column('P3', 'P3 Â· Nice to have')}
    </div>
  </div>

  <div class="panel" id="done" hidden>
    <div class="toolbar filters">
      <button aria-pressed="true" data-kind="all">All</button>
      <button aria-pressed="false" data-kind="feature">Features</button>
      <button aria-pressed="false" data-kind="process">Process</button>
      <button aria-pressed="false" data-kind="fix">Fixes</button>
    </div>
    ${done.map(doneRow).join('')}
  </div>

  <div class="panel" id="closed" hidden>
    ${closed
      .map(
        (item) => `
      <details class="card" data-search="${escape(`${item.id} ${item.text}`.toLowerCase())}">
        <summary><span class="id">${item.id}</span><span class="chip">closed by ${escape(item.closedBy)}</span><span class="title">${inline(item.title)}</span></summary>
        <div class="body"><p>${inline(item.text)}</p></div>
      </details>`,
      )
      .join('')}
  </div>

  <div class="panel" id="rejected" hidden>
    <table>
      <thead><tr><th>Proposal</th><th>Why rejected</th></tr></thead>
      <tbody>
      ${rejected.map((item) => `<tr data-search="${escape(`${item.title} ${item.why}`.toLowerCase())}"><td>${inline(item.title)}</td><td>${inline(item.why)}</td></tr>`).join('')}
      </tbody>
    </table>
  </div>
</main>
<script>
const tabs = document.querySelectorAll('[data-tab]');
tabs.forEach((tab) => tab.addEventListener('click', () => {
  tabs.forEach((t) => t.setAttribute('aria-selected', String(t === tab)));
  document.querySelectorAll('.panel').forEach((p) => { p.hidden = p.id !== tab.dataset.tab; });
  try { localStorage.setItem('board-tab', tab.dataset.tab); } catch {}
}));
try { const saved = localStorage.getItem('board-tab'); if (saved) document.querySelector('[data-tab="' + saved + '"]')?.click(); } catch {}
let kind = 'all';
let type = 'all';
const epicSelect = document.getElementById('epic');
const apply = () => {
  const q = document.getElementById('q').value.trim().toLowerCase();
  const epic = epicSelect.value;
  document.querySelectorAll('[data-search]').forEach((el) => {
    const byText = !q || el.dataset.search.includes(q);
    const byKind = !el.dataset.kind || kind === 'all' || el.dataset.kind === kind;
    const byType = !el.dataset.type || type === 'all' || el.dataset.type === type;
    const byEpic = el.dataset.epic === undefined || epic === 'all' || el.dataset.epic === epic;
    el.classList.toggle('hidden', !(byText && byKind && byType && byEpic));
  });
  document.querySelectorAll('[data-lane]').forEach((lane) => {
    const n = lane.querySelectorAll('.ticket:not(.hidden)').length;
    lane.querySelector(':scope > h3 [data-count], :scope > h4 [data-count]').textContent = n;
  });
};
document.getElementById('q').addEventListener('input', apply);
epicSelect.addEventListener('change', apply);
document.querySelectorAll('[data-type-filter]').forEach((b) => b.addEventListener('click', () => {
  type = b.dataset.typeFilter;
  document.querySelectorAll('[data-type-filter]').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
  apply();
}));
document.querySelector('.show-all')?.addEventListener('click', (e) => {
  document.querySelector('.scrum-done').classList.add('expanded');
  e.target.remove();
});
document.querySelectorAll('[data-kind]').forEach((b) => b.tagName === 'BUTTON' && b.addEventListener('click', () => {
  kind = b.dataset.kind;
  document.querySelectorAll('[data-kind]').forEach((x) => x.tagName === 'BUTTON' && x.setAttribute('aria-pressed', String(x === b)));
  apply();
}));
</script>
</body>
</html>
`;
}

const isMain = import.meta.url === pathToFileURL(process.argv[1] ?? '').href;
const html = isMain ? render(collect()) : '';

if (!isMain) {
  // imported for readEpics (LG-API-08): build nothing
} else if (process.argv[2] === 'check') {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== html) {
    console.error('docs/board.html is stale: run `pnpm board` and commit the result');
    process.exit(1);
  }
  console.log('docs/board.html matches the ledger and the backlog.');
} else {
  fs.writeFileSync(OUT, html);
  console.log('Wrote docs/board.html.');
}
